using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using MapSharedProps.EditorTools;
public static class Rock127Checks {
 static string Root=>Path.GetFullPath(Path.Combine(Application.dataPath,".."));static string Out=>Path.Combine(Root,"Evidence127Native");
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 [Serializable]class Row{public string tag,savedReload;public int prefabs,placed;public bool old48Preserved;}
 [Serializable]class Report{public bool pass;public Row[] cases;public string error;public string[] limitations;}
 static Report report=new Report();
 static string ReplaceOptional(string raw,string value){int key=raw.IndexOf("\"mineCutRockV1\"",StringComparison.Ordinal),start=raw.IndexOf('{',key),depth=0,end=start;bool quoted=false,escaped=false;Check(key>=0&&start>key,"optional fixture field");for(;end<raw.Length;end++){char c=raw[end];if(quoted){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='\"')quoted=false;continue;}if(c=='\"'){quoted=true;continue;}if(c=='{')depth++;if(c=='}'&&--depth==0){end++;break;}}Check(depth==0,"bounded JSON object");return raw.Substring(0,start)+value+raw.Substring(end);}
 public static void Run(){Directory.CreateDirectory(Out);try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rows=new List<Row>();var raw=File.ReadAllText(Path.Combine(Root,"Input127/small_props.json"));
 foreach(string tag in new[]{"valid","missing","badVersion","badIndex","badPng","nonfinite","nonSolid","compact","customCircle","customHeight"}){
  var data=JsonUtility.FromJson<SmallPropsV1.Data>(raw);if(tag=="missing")data.mineCutRockV1=null;if(tag=="badVersion")data.mineCutRockV1.version=999;if(tag=="badIndex")data.mineCutRockV1.assets[0].triangles[0]=999999;if(tag=="badPng")data.mineCutRockV1.textures.colour="invalid";if(tag=="nonfinite")data.mineCutRockV1.assets[0].positions[0]=float.NaN;if(tag=="nonSolid")data.mineCutRockV1.assets[0].radius=0;
  if(tag=="customHeight"){data.mineCutRockV1.assets[0].radius=.6f;data.mineCutRockV1.assets[0].height=1.3f;}
  if(tag=="customCircle"){var a=data.mineCutRockV1.assets[0];a.shape=false;a.radius=.5f;a.height=.8f;a.circleColliders=new[]{new SmallPropsV1.CircleProxy{center=new[]{0f,0f,0f},radius=.5f,height=.8f}};}
  bool valid=new[]{"valid","nonSolid","compact","customCircle","customHeight"}.Contains(tag);string dir=Path.Combine(Root,"Input127-active");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"small_props.json"),ReplaceOptional(raw,data.mineCutRockV1==null?"null":JsonUtility.ToJson(data.mineCutRockV1)));File.Copy(Path.Combine(Root,"Input127/props.csv"),Path.Combine(dir,"props.csv"),true);if(tag=="compact"){File.Copy(Path.Combine(dir,"small_props.json"),Path.Combine(dir,"small_props_library.json"),true);File.WriteAllText(Path.Combine(dir,"small_props.json"),"{\"version\":1,\"units\":\"metres\",\"axes\":\"Unity X/Y/Z\",\"library\":\"small_props_library.json\"}");}
  string folder="Assets/Imported127-"+tag;if(!AssetDatabase.IsValidFolder(folder))AssetDatabase.CreateFolder("Assets","Imported127-"+tag);var root=new GameObject("CutRock "+tag);var prefabs=new Dictionary<string,GameObject>();int placed=SmallPropsV1.Build(dir,folder,root.transform,Shader.Find("MapSharedProps/Lit"),prefabs);Check(prefabs.Count==(valid?49:48)&&placed==(valid?2:0),tag+" formal count/fallback");
  foreach(var kv in prefabs.Where(k=>k.Key!="mine_cut_rock")){var before=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported125-valid/small-"+kv.Key+".prefab");Check(before,"baseline48 "+kv.Key);Check(ColliderSnapshot109.MeshHash(before.GetComponent<MeshFilter>().sharedMesh)==ColliderSnapshot109.MeshHash(kv.Value.GetComponent<MeshFilter>().sharedMesh),tag+" unchanged mesh "+kv.Key);var bc=before.GetComponentsInChildren<Collider>(true);var ac=kv.Value.GetComponentsInChildren<Collider>(true);Check(bc.Length==ac.Length,tag+" actual collider count "+kv.Key);if(bc.Length>0)Check(ColliderSnapshot109.Capture(before)==ColliderSnapshot109.Capture(kv.Value),tag+" collider geometry "+kv.Key);}
  string reload="not applicable: rejected/missing optional";if(valid){var cart=prefabs["mine_cut_rock"];var renderer=cart.GetComponent<MeshRenderer>();var mat=renderer.sharedMaterial;Check(mat.shader.name=="Universal Render Pipeline/Lit"&&mat.GetColor("_BaseColor")==Color.white&&Empty(renderer),"persistent standard Lit without MPB");var mesh=cart.GetComponent<MeshFilter>().sharedMesh;Check(mesh.uv.Length==mesh.vertexCount&&mesh.tangents.Length==mesh.vertexCount,"UV tangent contract");Check(mat.IsKeywordEnabled("_NORMALMAP")&&mat.IsKeywordEnabled("_METALLICSPECGLOSSMAP"),"data maps enabled");
   var cs=cart.GetComponents<Collider>();Check(cs.Length==(tag=="nonSolid"?0:1),"nonSolid keeps rock visual only");if(tag=="customCircle"){var c=cart.GetComponent<MeshCollider>();Check(c&&c.sharedMesh&&Vector3.Distance(c.sharedMesh.bounds.size,new Vector3(1,.8f,1))<1e-5,"custom cylinder persisted");}else if(tag!="nonSolid"){var c=cart.GetComponent<BoxCollider>();var h=tag=="customHeight"?1.3f:1.92f;Check(c&&c.size==new Vector3(1.82f,h,.36f)&&c.center==new Vector3(0,h/2,-.12f),"actual shallow wall collider");}
   var expected=root.GetComponentsInChildren<MeshRenderer>().Select(x=>x.sharedMaterial).ToArray();var expectedMesh=root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).ToArray();var pose=root.transform.Cast<Transform>().Select(t=>t.localToWorldMatrix).ToArray();string save=folder+"/placed.prefab";var asset=PrefabUtility.SaveAsPrefabAsset(root,save);UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(asset);Check(root.GetComponentsInChildren<MeshRenderer>().Select(x=>x.sharedMaterial).SequenceEqual(expected)&&root.GetComponentsInChildren<MeshRenderer>().All(Empty),"save destroy instantiate material colour");Check(root.GetComponentsInChildren<MeshFilter>().Select(x=>x.sharedMesh).SequenceEqual(expectedMesh)&&root.transform.Cast<Transform>().Select(t=>t.localToWorldMatrix).SequenceEqual(pose),"save mesh/pose");reload="passed save-destroy-reinstantiate";
  } rows.Add(new Row{tag=tag,prefabs=prefabs.Count,placed=placed,savedReload=reload,old48Preserved=true});UnityEngine.Object.DestroyImmediate(root);GC.Collect();
 }
 AssetDatabase.SaveAssets();Studio();report.pass=true;report.cases=rows.ToArray();report.limitations=new[]{"Background Editor only; Player/mobile/GPU timing not measured.","Old Reader binary not executed; unknown optional field follows previous source control flow.","Standalone facing; no original walls or fixed rock samples replaced."};Save();EditorApplication.Exit(0);
 }catch(Exception e){report.error=e.ToString();Save();Debug.LogException(e);EditorApplication.Exit(1);}}
 static bool Empty(Renderer r){var b=new MaterialPropertyBlock();r.GetPropertyBlock(b);return b.isEmpty;}
 static void Save(){File.WriteAllText(Path.Combine(Out,"checks.json"),JsonUtility.ToJson(report,true));}
 static void Studio(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.16f,.18f,.2f);var plane=GameObject.CreatePrimitive(PrimitiveType.Plane);var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.color=new Color(.24f,.21f,.17f);plane.GetComponent<Renderer>().sharedMaterial=mat;var light=new GameObject("diagnostic sun").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.3f;light.shadows=LightShadows.Soft;light.transform.rotation=Quaternion.Euler(45,-30,0);var camera=new GameObject("offscreen").AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.08f,.09f,.1f);camera.fieldOfView=45;camera.nearClipPlane=.02f;
 var rock=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported127-valid/small-mine_cut_rock.prefab"));var target=rock.GetComponent<Renderer>().bounds.center;
 foreach(string view in new[]{"normal","close","opposite","back","dark","point","spot"}){light.enabled=view!="dark"&&view!="point"&&view!="spot";light.transform.rotation=Quaternion.Euler(45,view=="opposite"?60:-30,0);RenderSettings.ambientLight=view=="dark"?Color.black:new Color(.16f,.18f,.2f);Light local=null;if(view=="point"||view=="spot"){local=new GameObject("diagnostic local light").AddComponent<Light>();local.type=view=="spot"?LightType.Spot:LightType.Point;local.transform.position=new Vector3(-1.1f,1.6f,-1.5f);local.transform.LookAt(target);local.range=5;local.intensity=4;local.spotAngle=80;local.shadows=LightShadows.Soft;}camera.transform.position=target+(view=="normal"?new Vector3(0,9,-6.3f):view=="back"?new Vector3(-2.2f,1.2f,3):new Vector3(1.3f,1.2f,-3));camera.transform.LookAt(target);var image=Shared117Review.Image(camera,1600,900);File.WriteAllBytes(Path.Combine(Out,view+".png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);if(local)UnityEngine.Object.DestroyImmediate(local.gameObject);}UnityEngine.Object.DestroyImmediate(rock);
 RenderSettings.ambientLight=new Color(.16f,.18f,.2f);light.enabled=true;
 LoadCheck(camera);
 }
 [Serializable]class Load{public int placed,visible,meshes,materials,textures;public long meshBytes,textureBytes;public double cpuRenderMedianMs;public bool gpuMeasured=false;}
 static void LoadCheck(Camera camera){var rows=new List<Load>();foreach(int count in new[]{9,225}){var objects=new List<GameObject>();int side=count==9?3:15;for(int i=0;i<count;i++){var o=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Imported127-valid/small-mine_cut_rock.prefab"));o.transform.position=new Vector3((i%side-side/2)*2,0,(i/side-side/2)*2);objects.Add(o);}camera.transform.position=new Vector3(0,30,-24);camera.transform.LookAt(Vector3.zero);var rt=new RenderTexture(1280,720,24);rt.Create();camera.targetTexture=rt;var cpu=new List<double>();for(int i=0;i<12;i++){var watch=System.Diagnostics.Stopwatch.StartNew();camera.Render();watch.Stop();if(i>=6)cpu.Add(watch.Elapsed.TotalMilliseconds);}var meshes=objects.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().ToArray();var mats=objects.Select(o=>o.GetComponent<Renderer>().sharedMaterial).Distinct().ToArray();var textures=mats.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_MetallicGlossMap"),m.GetTexture("_BumpMap")}).Distinct().ToArray();Check(meshes.Length==1&&mats.Length==1&&textures.Length==3,"bounded sharing");var planes=GeometryUtility.CalculateFrustumPlanes(camera);rows.Add(new Load{placed=count,visible=objects.Count(o=>GeometryUtility.TestPlanesAABB(planes,o.GetComponent<Renderer>().bounds)),meshes=meshes.Length,materials=mats.Length,textures=textures.Length,meshBytes=meshes.Sum(m=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m)),textureBytes=textures.Sum(t=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t)),cpuRenderMedianMs=cpu.OrderBy(x=>x).ElementAt(cpu.Count/2)});camera.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);foreach(var o in objects)UnityEngine.Object.DestroyImmediate(o);}File.WriteAllText(Path.Combine(Out,"load.json"),"{\"cases\":["+string.Join(",",rows.Select(r=>JsonUtility.ToJson(r)))+"],\"limitation\":\"CPU Render submission, not GPU or game-frame guarantee\"}");}
}
